// The CloudFormation resource-type -> open-infra kind mapping table.
//
// This table is the ENGINE'S PUBLIC CONTRACT and the honesty rail: the engine can only
// provision a resource type listed here as `supported` (or, with caveats, `partial`).
// Anything not in this table — or listed `unsupported`/`gated` — is refused. The default
// for an unknown type is `unsupported`. There is deliberately no catch-all that maps an
// unrecognized type to "something close"; a type we cannot fully model must fail loud.
//
// Statuses:
//
//	supported   — a backing kind exists and the mapping is faithful.
//	partial     — a backing kind exists but the mapping is lossy (some properties don't
//	              translate, or it is provisioned as part of another kind); the caveat is
//	              surfaced loudly and the type is NOT claimed as full CFN compatibility.
//	gated       — a backing kind is not yet available (blocked on another issue); refused.
//	unsupported — no backing kind, or explicitly out of scope for v1; refused.
package cfn

import "strings"

type Status string

const (
	Supported   Status = "supported"
	Partial     Status = "partial"
	Gated       Status = "gated"
	Unsupported Status = "unsupported"
)

type MapEntry struct {
	Kind   string // the open-infra kind (or the primitive), empty when unsupported
	Status Status
	Note   string
}

// mappingTable is the seed. Grow it deliberately, the gated way every capability graduates
// here — a type is added only once it has a backing kind and a faithful mapping.
var mappingTable = map[string]MapEntry{
	// --- supported: a faithful backing kind ---
	"AWS::Lambda::Function": {Kind: "Function", Status: Supported, Note: "scale-to-zero Function. A .zip package (the default PackageType) runs on a managed runtime: Runtime nodejs20.x / nodejs22.x / python3.12 / python3.13 / dotnet8 (any other refuses, naming these), Handler, and Code.ZipFile (index.js / index.py, as CloudFormation writes it) or Code.S3Bucket/S3Key (+ S3ObjectVersion), read at deploy with the caller's s3:GetObject and stored as Lambda stores it — through the aws-shim front door; the CLI deploys inline code as a ConfigMap and refuses an S3 package. Layers and inline cfn-response refuse. PackageType: Image runs Code.ImageUri. Role maps to spec.role, the execution role the function's code runs as (its SDK assumes it on the aws-shim, no keys): an in-stack AWS::IAM::Role by !GetAtt <Role>.Arn, or a role ARN of the stack's account; a !Ref (a name, not an ARN), a role that does not trust lambda.amazonaws.com and another account's role refuse, as Lambda refuses them"},
	"AWS::Lambda::Version":  {Kind: "Function(revision)", Status: Partial, Note: "a published Lambda version -> a Knative revision, auto-created on each deploy of a kind: Function. It is an EMERGENT runtime object, not a template-declarable resource, and no revision name exists at translate time to pin. Plan-recognized, NOT create-deployable (Deployable=false): a stack referencing a Version is understood but provisions nothing on its own — roll out new code by updating the kind: Function and shift traffic with spec.aliases."},
	"AWS::Lambda::Alias":    {Kind: "Function(spec.aliases)", Status: Partial, Note: "a Lambda alias -> a weighted Knative traffic tag on a kind: Function (spec.aliases: name+revision+weight; the aws-shim Invoke doorway routes a Qualifier to the <alias>-<function> tag, #257). Plan-recognized, NOT create-deployable (Deployable=false): an AWS alias points at a published numbered Version (no translate-time analog — Knative assigns revision names at apply) and its RoutingConfig weights two such versions, so the alias->revision binding can't be derived from the template — declare traffic via kind: Function spec.aliases natively."},
	// Partial, not Supported: the ASL is translated byte-for-byte for the SUPPORTED subset (Task via
	// function:<name>, Choice/Wait/Pass/Succeed/Fail, Retry with backoff, Catch), but the create
	// translator REFUSES what the engine does not run — matching the aws-shim Step Functions doorway's
	// own carve-outs: EXPRESS type, Parallel/Map states, the .waitForTaskToken/.sync
	// callback patterns, non-Lambda service integrations, and AWS-ARN/S3-location Task definitions. A
	// template using any of those blocks at the translate gate rather than being planned as full parity.
	"AWS::StepFunctions::StateMachine": {Kind: "StateMachine", Status: Partial, Note: "Amazon States Language engine; the supported subset (Task->function:<name>, Choice/Wait/Pass/Succeed/Fail, Parallel, Map, Retry/Catch) translates byte-for-byte. EXPRESS (StateMachineType), AWS-ARN Task Resources (remap to function:<name>), .waitForTaskToken/.sync callbacks, and non-Lambda service integrations REFUSE (the #172 doorway carve-outs)"},
	"AWS::AppSync::GraphQLApi":         {Kind: "GraphQLApi", Status: Supported, Note: "resolver-first GraphQL"},
	"AWS::IAM::Role":                   {Kind: "Role", Status: Partial, Note: "kind: Role is a first-class assumable identity (trust policy + attached data-plane Policies; sts:AssumeRole issues temporary session credentials on the aws-shim — #111/#174). A create translator provisions SERVICE roles: an AssumeRolePolicyDocument allowing sts:AssumeRole for AWS service principals records each as IAM's CreateRole does — ec2.amazonaws.com as spec.trust vm (assumable by a kind: VirtualMachine that names it as spec.instanceRole, the container-credentials path), lambda.amazonaws.com as Service::lambda.amazonaws.com (a Lambda execution role, assumed by a kind: Function that names it as spec.role), ecs-tasks.amazonaws.com as Service::ecs-tasks.amazonaws.com (an ECS task role, assumed by a kind: Application that names it as spec.assumeRole), states.amazonaws.com as Service::states.amazonaws.com (assumed by a state machine that names it), any other service as Service::<service>, which no open-infra service assumes on, so it grants nothing — a caveat. An AppSync service role (trusting appsync.amazonaws.com) translates with no trust entry: the role exists with its policies, but nothing assumes it (open-appsync reaches its data sources with its own connection), so it grants nothing — a caveat. A non-service trust principal (account/ARN, SAML/OIDC, a mix with one of those) REFUSES. Inline Policies are translated into companion kind: Policy objects (spec.dataPlane, appliesTo Role::<name>) that govern the role's assumed sessions — the narrow s3/sqs/ecr/… data-plane subset on recognizable ARNs (an in-stack resource referenced by !GetAtt X.Arn, or by ${X.Arn}/${X} inside an Fn::Sub, resolves to its ARN); an unfaithful statement fail-closes the Role. ManagedPolicyArns stay a caveat (AWS-managed policies are not attached — express the access as inline statements)."},
	"AWS::IAM::ManagedPolicy":          {Kind: "Policy", Status: Supported, Note: "like IAM::Policy: a create translator imports the DATA-PLANE part into an enforced kind: Policy spec.dataPlane when the ManagedPolicy carries inline Groups/Users/Roles attachments (a Roles attachment governs the assumed sts:AssumeRole session, #111); a standalone ManagedPolicy (attached via ManagedPolicyArns) has no principal here and BLOCKS, as does any control-plane/unmappable/conditioned part"},
	"AWS::IAM::Policy":                 {Kind: "Policy", Status: Supported, Note: "inline policy -> a Policy; a create translator imports the DATA-PLANE part (s3/dynamodb/lambda actions on recognizable ARNs, no conditions) into an enforced kind: Policy spec.dataPlane, and BLOCKS anything it can't honor faithfully (control-plane/unmappable/conditioned parts) — narrow the policy or author it natively"},
	"AWS::IAM::User":                   {Kind: "User", Status: Supported},
	"AWS::IAM::Group":                  {Kind: "Group", Status: Partial, Note: "maps at plan, but no create translator (Deployable=false): a Group's permissions are its attached AWS policies (unmappable automatically), and its required clusterRole can't be derived from them — author the Group + its policy attachment natively"},
	"AWS::IAM::InstanceProfile":        {Kind: "(implicit)", Status: Partial, Note: "the AWS container that binds a Role to an instance. open-infra binds the role directly on the VM (kind: VirtualMachine spec.instanceRole), so the profile provisions nothing on its own — an EC2::Instance's IamInstanceProfile is resolved THROUGH it to the role name. A create translator accepts it as a no-op (Roles/Path/Name/Tags), so a stack carrying it is no longer blocked."},
	"AWS::KMS::Key":                    {Kind: "EncryptionKey", Status: Supported, Note: "customer key in Vault Transit (kind: EncryptionKey — what an encrypted EBS volume is keyed by). Through the aws-shim CloudFormation front door with KMS served, also a key in the KMS API's store under the id the stack's Ref/Arn report (ListKeys/Encrypt/Decrypt; its KeyPolicy applied as that front door applies key policies; deleted with the pending window). Symmetric ENCRYPT_DECRYPT keys only there."},
	"AWS::KMS::Alias":                  {Kind: "KMSAlias", Status: Partial, Note: "an alias in the aws-shim KMS API's store (CreateAlias), targeting an in-stack key's KMS id or a key id/ARN. Needs the KMS front door (the aws-shim CloudFormation doorway with KMS served); refuses on any other deploy path."},
	"AWS::SQS::QueuePolicy":            {Kind: "SQSQueuePolicy", Status: Partial, Note: "the Policy attribute of each queue it names, in the aws-shim SQS API's store, where it decides the deliveries the shim makes to the queue: an SNS topic's (sns.amazonaws.com) or EventBridge rule's (events.amazonaws.com) SendMessage, by service principal or by \"*\" narrowed with aws:SourceArn/aws:SourceAccount. A grant to a user or role, a public grant, or any other condition refuses (callers are authorized by IAM). Needs the SQS front door; refuses on any other deploy path."},
	"AWS::SNS::TopicPolicy":            {Kind: "SNSTopicPolicy", Status: Partial, Note: "the Policy attribute of each topic it names, in the aws-shim SNS API's store, where it decides the publishes the shim makes to the topic (a CloudWatch alarm's, cloudwatch.amazonaws.com), by service principal or by \"*\" narrowed with aws:SourceArn/aws:SourceAccount/aws:SourceOwner. A grant to a user or role, a public grant, or any other condition refuses (callers are authorized by IAM). Needs the SNS front door; refuses on any other deploy path."},

	// --- partial: backing kind exists but the mapping is lossy ---
	"AWS::S3::Bucket":                       {Kind: "Bucket", Status: Partial, Note: "a standalone MinIO bucket (kind: Bucket) with versioning + lifecycle; Object Lock (WORM retention) maps to a MinIO lock-enabled bucket; an in-stack AWS::S3::BucketPolicy collates in as spec.policy (public \"*\" principals only — AWS-IAM-ARN principals refuse); BucketEncryption maps with a caveat when the deploy environment reports object encryption on (every new bucket gets default AES256 encryption under the platform MinIO's key — the platform default, not per-bucket) and refuses otherwise rather than deploy an unencrypted bucket; CorsConfiguration is a MinIO ceiling (MinIO does CORS globally via MINIO_API_CORS_ALLOW_ORIGIN, not per bucket — PutBucketCors returns MalformedXML) and refuses loudly; website/replication do not map"},
	"AWS::S3::BucketPolicy":                 {Kind: "Bucket", Status: Supported, Note: "collated into its in-stack AWS::S3::Bucket as spec.policy; * (public) principals only — AWS-IAM-ARN principals refuse; not standalone"},
	"AWS::SQS::Queue":                       {Kind: "Queue", Status: Partial, Note: "a standalone managed queue (kind: Queue) — a NATS JetStream WorkQueue stream. FIFO maps: FifoQueue/.fifo -> strict per-message-group ordering (each MessageGroupId is a <queue>.<group> subject token; groups run in parallel) + a 5m publish-dedup window (Nats-Msg-Id, from MessageDeduplicationId). Per-queue encryption does NOT map (NATS encryption is substrate-level); ContentBasedDeduplication needs a producer-set Nats-Msg-Id (no auto-hash front door); visibility/delay/DLQ are consumer-side caveats. Through the aws-shim CloudFormation front door with SQS served, instead a queue in the SQS API's own store — standard or FIFO (FifoQueue/ContentBasedDeduplication/DeduplicationScope/FifoThroughputLimit are the FIFO queue's attributes; an unnamed one gets the .fifo suffix): VisibilityTimeout/DelaySeconds/MessageRetentionPeriod/MaximumMessageSize/ReceiveMessageWaitTimeSeconds/RedrivePolicy are its queue attributes, honored by that store; Ref is the queue URL, Arn/QueueName/QueueUrl resolve."},
	"AWS::SNS::Topic":                       {Kind: "Queue", Status: Partial, Note: "a standalone fan-out topic (kind: Queue, fanout) — a NATS JetStream Limits stream. An inline lambda Subscription to an in-stack Function maps (the subscribing kind: Function gets the topic in spec.queues and reads the stream); every other inline Subscription protocol (sqs/http/email/sms/...) refuses honestly, as do FIFO and encryption. Through the aws-shim CloudFormation front door with SNS served, instead a topic in the SNS API's own store; inline sqs and lambda Subscriptions become subscriptions there, delivered by that front door (Publish → the stack's queue / an invoke of the Function)."},
	"AWS::SNS::Subscription":                {Kind: "Function", Status: Partial, Note: "collated into the subscribing kind: Function via spec.queues, not standalone. ONLY a lambda subscription whose Endpoint is an in-stack AWS::Lambda::Function maps (the Function reads the topic's JetStream stream directly); an out-of-stack topic/endpoint refuses, an sqs sub refuses (open-infra builds no topic→queue bridge — point the consumer at the topic stream via spec.queues), and http/email/sms/application/firehose refuse (no outward push-delivery surface). Through the aws-shim CloudFormation front door with SNS served, instead a subscription in the SNS API's store on an in-stack topic: sqs (a queue ARN) and lambda (an in-stack Function, or a function ARN) are delivered by that front door; RawMessageDelivery, FilterPolicy and FilterPolicyScope map (that front door applies the filter policy; one it cannot apply refuses); other delivery settings refuse."},
	"AWS::RDS::DBInstance":                  {Kind: "Application(database)", Status: Partial, Note: "managed DB via an Application's database block. Engine maps (postgres/aurora-postgresql->CNPG; mysql/mariadb/aurora-mysql->MariaDB; sqlserver-*->babelfish); AllocatedStorage->storage size and common DBInstanceClasses->CPU/memory requests (a documented mapping table). Burst-credit accounting, EBS-optimized throughput, Aurora distributed storage, StorageType/provisioned-IOPS do NOT map; an unknown class falls back to engine defaults with a caveat."},
	"AWS::EC2::VPC":                         {Kind: "Vpc", Status: Partial, Note: "a create translator provisions a kind: Vpc (kube-ovn network domain; #120). The VPC-level CidrBlock is informational (subnets carry the CIDRs); DNS/tenancy/tags don't map."},
	"AWS::EC2::Subnet":                      {Kind: "Subnet", Status: Partial, Note: "a create translator provisions a kind: Subnet with real OVN isolation (#120): CidrBlock->cidr, a VpcId !Ref to an in-stack AWS::EC2::VPC->vpc, MapPublicIpOnLaunch->private (public=>not private). AZ/IPv6/tags don't map."},
	"AWS::EC2::SecurityGroup":               {Kind: "SecurityGroup", Status: Partial, Note: "a create translator provisions a kind: SecurityGroup (default-deny allow-rules). Inline SecurityGroupIngress/Egress AND standalone AWS::EC2::SecurityGroupIngress/Egress resources !Ref'ing this group collate into spec.ingress/egress, FAIL-CLOSED: TCP/UDP single-port, a range of up to 16 ports (expanded to its exact port list), or all-ports, with a CidrIp source or a SourceSecurityGroupId !Ref to an in-stack SG translate; a non-TCP/UDP protocol (incl. \"-1\"), a port range wider than 16 ports, an out-of-stack SG id, or an IPv6 CIDR REFUSE the whole resource (never a looser rule). VpcId scope, GroupName/tags don't map."},
	"AWS::EC2::SecurityGroupIngress":        {Kind: "SecurityGroup", Status: Partial, Note: "collated into the in-stack AWS::EC2::SecurityGroup its GroupId !Refs (spec.ingress), not standalone; a rule on an out-of-stack group refuses. Same fail-closed rule fidelity as the inline form."},
	"AWS::EC2::SecurityGroupEgress":         {Kind: "SecurityGroup", Status: Partial, Note: "collated into the in-stack AWS::EC2::SecurityGroup its GroupId !Refs (spec.egress), not standalone; a rule on an out-of-stack group refuses. Same fail-closed rule fidelity as the inline form."},
	"AWS::EC2::VPCEndpoint":                 {Kind: "VpcEndpoint", Status: Partial, Note: "a create translator provisions a kind: VpcEndpoint — a private, in-VPC DNS alias to the one aws-shim front door for the service. ServiceName->service, VpcEndpointType carried for fidelity, a VpcId !Ref to an in-stack AWS::EC2::VPC->vpc. PolicyDocument/RouteTableIds/SubnetIds/SecurityGroupIds/PrivateDnsEnabled don't map: every service routes to the shim and access through the endpoint is governed by IAM/Cedar at the shim, not a per-endpoint policy."},
	"AWS::EC2::Instance":                    {Kind: "VirtualMachine", Status: Partial, Note: "a create translator provisions a kind: VirtualMachine (#115). ImageId names an open-infra catalog OS in place of the AMI — a raw ami- id or an out-of-catalog OS refuses with the catalog listed; a recognized PUBLIC image SSM-parameter path (ubuntu/debian/fedora/windows) maps. InstanceType->CPU/memory (common types), UserData->cloud-init (#! scripts; #cloud-config isn't merged), root BlockDeviceMapping->diskSize; an Encrypted root->spec.rootDisk (LUKS on longhorn-encrypted, keyed like an encrypted data disk; the OS image is copied onto it before first boot, and it is RWO). SubnetId->places the VM in a kind: Subnet (real OVN isolation, #120; a raw subnet- id refuses like an AMI). SecurityGroupIds / the primary NetworkInterfaces[0] attach kind: SecurityGroups via spec.securityGroups and set the subnet; AssociatePublicIpAddress->spec.expose (a raw sg- id refuses). Extra EBS BlockDeviceMappings map to spec.dataDisks (blank virtio disks; udev rules keyed by each disk's serial alias the AWS Nitro names (/dev/nvme0n1 root, /dev/nvme1n1…) and each mapping's DeviceName with its sd/xvd twin onto them, so a lift-and-shift UserData script runs unmodified; an Encrypted device maps to a LUKS data disk keyed by a customer kind: EncryptionKey — KmsKeyId !Refs an in-stack AWS::KMS::Key, or omit it for the per-namespace default key (AWS aws/ebs analog, created on first use) — and is RWO, so it pins a highAvailability VM's live migration; a KmsKeyId that does not map to an in-stack key refuses). IamInstanceProfile resolves through its in-stack AWS::IAM::InstanceProfile to the AWS::IAM::Role and binds spec.instanceRole (the Linux guest gets that kind: Role's rotating credentials from EC2 instance metadata at 169.254.169.254, no static keys). MetadataOptions->spec.metadataOptions (HttpTokens / HttpPutResponseHopLimit / HttpEndpoint 1:1; HttpProtocolIpv6 and InstanceMetadataTags enabled are caveats — the IPv6 endpoint and instance tags are not served). KeyName carries a key pair the account holds (ec2 import-key-pair) into spec.sshKey, and one it does not hold refuses (InvalidKeyPair.NotFound); AZ doesn't map; Tags, the InstanceType and the KeyName are kept as the VM's AWS view, which the aws-shim's EC2 API reports. An update that changes what the instance reads at start (InstanceType, UserData, disks, MetadataOptions, IamInstanceProfile) stops and starts it and completes once it runs on the new spec, as AWS's \"some interruptions\" update does; security groups and the public address apply live. Ref and Fn::GetAtt InstanceId are the i- id the guest's instance metadata reports (the VM's status.instanceId; the aws-shim's EC2 and SSM APIs take it). Fn::GetAtt: AvailabilityZone, PrivateIp, PublicIp (the VM's LAN IP), PrivateDnsName (AWS's ip-a-b-c-d.ec2.internal form for the VM's address; nothing serves that zone here, a caveat) and PublicDnsName (ec2-<LAN IP with dashes>.<the install's public DNS suffix>, which a site points at a LAN-resolvable wildcard zone; \"\" without a suffix or for an instance with no public address, as AWS reports it then)."},
	"AWS::EC2::Volume":                      {Kind: "Volume", Status: Partial, Note: "block volume (Longhorn); Size and Encrypted map faithfully (Encrypted -> LUKS keyed by a customer kind: EncryptionKey; KmsKeyId references an in-stack KMS::Key, or omit it for the per-namespace default key — the AWS aws/ebs analog, created on first use; a KmsKeyId that does not map to an in-stack key refuses). VolumeType/Iops/Throughput do NOT map: Longhorn is replica-based durability, not provisioned IOPS — mapping an IOPS number would fabricate a performance contract, so it stays explicitly unmapped. AZ has no equivalent."},
	"AWS::EC2::EIP":                         {Kind: "VirtualMachine(spec.expose)", Status: Partial, Note: "an Elastic IP associated with an in-stack AWS::EC2::Instance (its InstanceId, or an AWS::EC2::EIPAssociation) maps onto that VM's LAN IP (#347 1.6): the kind: VirtualMachine gets spec.expose (a MetalLB LoadBalancer carrying SSH 22/RDP 3389) plus spec.ports derived from the TCP/UDP ports the instance's in-stack SecurityGroups admit from a CIDR (single ports 1:1, ranges of up to 16 ports expand; all-ports, wider ranges, protocol -1 and SG-sourced rules are caveats, never published). The EIP provisions nothing standalone. Caveats: a LAN address, not a public internet IP; stable for the VM's life but held by its LoadBalancer Service, so a replaced VM may draw a new IP; Ref/GetAtt PublicIp are assigned at apply (a stack Output reading them returns the VM's status.lanIp once the stack completes); where another resource embeds them (an instance's UserData, with the EIP associated by an EIPAssociation), the aws-shim's front door makes the EIP an allocation of its own created first, so the address is filled in at create, as on AWS; GetAtt AllocationId is a stable synthetic eipalloc- id. An EIP associated with nothing in its stack is, through the aws-shim's front door, an allocation of its own (#347 item 8): a LAN address the shim holds for the stack (a MetalLB address on a holder Service) that an EIPAssociation in another stack associates by its AllocationId — the address follows that stack's instance and stays with the allocation when it goes; Ref/GetAtt PublicIp are that address; releasing it while associated fails (InvalidIPAddress.InUse), as on AWS. REFUSES: an EIP associated with nothing in the stack where no allocations are kept (the cfn CLI), an out-of-stack InstanceId, more than one EIP on one instance (one LAN IP per VM), a specific/BYOIP address (Address/PublicIpv4Pool/IpamPoolId/TransferAddress), and an EIP used as an AWS::EC2::NatGateway AllocationId — that border-device case is kind: NatGateway + kind: ElasticIp, authored natively."},
	"AWS::EC2::EIPAssociation":              {Kind: "VirtualMachine(spec.expose)", Status: Partial, Note: "binds an in-stack AWS::EC2::EIP (AllocationId !GetAtt <EIP>.AllocationId, or EIP !Ref <EIP>) to an in-stack AWS::EC2::Instance (InstanceId) — folded onto that VM's LAN IP exactly like the EIP's own InstanceId (spec.expose + SecurityGroup-derived spec.ports); provisions nothing standalone. PrivateIpAddress is a caveat (the LAN IP forwards to the VM's single address). An AllocationId from another stack (a parameter or Fn::ImportValue naming that stack's GetAtt <EIP>.AllocationId) gives the instance's VM that allocation's address (spec.elasticIp, through the aws-shim's front door): the caller must be allowed ec2:AssociateAddress on it, it must exist, and an allocation already associated with another instance refuses (Resource.AlreadyAssociated). REFUSES: NetworkInterfaceId (no standalone ENI is modeled — associate by InstanceId), an out-of-stack instance, an AllocationId that is not one open-infra holds (an AWS account's), an address-form EIP from another stack (associate it by AllocationId), and a second EIP on the same instance."},
	"AWS::EC2::NatGateway":                  {Kind: "NatGateway", Status: Partial, Note: "a NAT gateway -> kind: NatGateway (a kube-ovn VpcNatGateway; SNAT egress + the flat-LAN border device, #120). Plan-recognized, NOT create-deployable (Deployable=false): the gateway's internalIp (lanIp) and VPC binding are not carried by the template (AWS auto-assigns them) and inventing an IP would fabricate the route anchor — author kind: NatGateway natively. ConnectivityType/AllocationId/MaxDrainDuration don't map."},
	"AWS::EC2::InternetGateway":             {Kind: "(implicit)", Status: Partial, Note: "on open-infra the border device is a kind: NatGateway (which serves both the NAT-GW and, on a flat /24, the Internet-Gateway role); a standalone InternetGateway provisions nothing. Public reachability is attached with kind: ElasticIp + a kind: Vpc default route to the gateway."},
	"AWS::EC2::VPCGatewayAttachment":        {Kind: "(implicit)", Status: Partial, Note: "the IGW<->VPC attachment is implied by a kind: NatGateway plus the VPC's default route (kind: Vpc spec.routes); provisions nothing on its own."},
	"AWS::EC2::NetworkAcl":                  {Kind: "Subnet(acls)", Status: Partial, Note: "a Network ACL -> the acls on a kind: Subnet (stateless OVN switch rules, #120). Plan-recognized, NOT create-deployable: an AWS NetworkAcl is a reusable rule set attached to subnets via separate NetworkAclEntry + SubnetNetworkAclAssociation resources; author the rules directly on the target kind: Subnet spec.acls."},
	"AWS::EC2::NetworkAclEntry":             {Kind: "Subnet(acls)", Status: Partial, Note: "one rule of a Network ACL -> one entry in a kind: Subnet spec.acls (direction/action/protocol/cidr/port); authored on the subnet, not standalone."},
	"AWS::EC2::SubnetNetworkAclAssociation": {Kind: "(implicit)", Status: Partial, Note: "the ACL<->subnet association is implicit: rules live directly on the target kind: Subnet spec.acls; provisions nothing on its own."},
	"AWS::EC2::VPCPeeringConnection":        {Kind: "Vpc(peerings)", Status: Partial, Note: "VPC peering -> kind: Vpc spec.peerings on BOTH VPCs + a spec.routes entry each (#120). Plan-recognized, NOT create-deployable: the /30 interconnect IPs are not carried by the template and peering is two-sided VPC config — author it on both kind: Vpc. Non-transitive, like AWS."},
	"AWS::EC2::TransitGateway":              {Kind: "TransitGateway", Status: Partial, Note: "a transit hub -> kind: TransitGateway (a subnet-less kube-ovn Vpc that peers every spoke; #120). Plan-recognized, NOT create-deployable: the per-spoke /30 links + each spoke's own attachment/route wiring aren't derivable from the template — author kind: TransitGateway (hub) + each spoke's kind: Vpc."},
	"AWS::EC2::TransitGatewayAttachment":    {Kind: "TransitGateway", Status: Partial, Note: "a TGW<->VPC attachment -> one entry in kind: TransitGateway spec.attachments plus the spoke's own kind: Vpc peering+route; authored, not standalone."},
	"AWS::EC2::RouteTable":                  {Kind: "Vpc(routes)", Status: Partial, Note: "a route table is a pure container — in kube-ovn routes are VPC-scoped (kind: Vpc spec.routes), not a standalone table, so a RouteTable provisions nothing on its own; its routes are the AWS::EC2::Route resources. A create translator accepts it as a no-op (VpcId/Tags only), so a stack carrying it is no longer blocked."},
	"AWS::EC2::Route":                       {Kind: "Vpc(routes)", Status: Partial, Note: "one route. ONLY the default route 0.0.0.0/0 (or ::/0) -> an in-stack AWS::EC2::InternetGateway translates, and it is implicit (provisions nothing): on open-infra a public subnet's internet egress is a property of the kind: NatGateway border device, and the VPC's default route to it is set when that gateway is authored natively. Any other route — a non-default CIDR, or a target that is not an in-stack InternetGateway (NatGateway/peering/instance/raw id) — REFUSES fail-closed (its next-hop IP is not template-derivable): author it on kind: Vpc spec.routes (cidr -> the NatGateway internalIp)."},
	"AWS::EC2::SubnetRouteTableAssociation": {Kind: "(implicit)", Status: Partial, Note: "route-table<->subnet association is implicit: kube-ovn routes are VPC-scoped (kind: Vpc spec.routes), not per-subnet-table; provisions nothing on its own."},
	"AWS::EC2::FlowLog":                     {Kind: "FlowLog", Status: Partial, Note: "VPC flow logs -> kind: FlowLog (OVS sFlow -> a node-local collector -> Loki; #120). Plan-recognized, NOT create-deployable: OVS sFlow is per-bridge/per-node (scope to a VPC/subnet by filtering records on CIDR in Loki), and the AWS ResourceId (a vpc-/subnet-/eni- id) + LogDestination (CloudWatch/S3) don't map — author kind: FlowLog natively. TrafficType ALL only (sampled)."},
	"AWS::EFS::FileSystem":                  {Kind: "FileShare", Status: Partial, Note: "maps at plan, but no create translator by design: EFS is elastic (no size) and kind: FileShare requires a size — inventing one would be a guess"},
	// Faithfully translated AS PART OF their parent AWS::AppSync::GraphQLApi (schema SDL / VTL /
	// APPSYNC_JS carried byte-for-byte via the collation) — NOT lossy, so not "partial". They are
	// simply not standalone: a bare one whose ApiId names no in-stack GraphQLApi refuses at deploy
	// (an orphan, not a silent success). See #118.
	"AWS::AppSync::DataSource":            {Kind: "GraphQLApi", Status: Supported, Note: "faithfully translated as part of its parent GraphQLApi; not standalone — a bare one (no in-stack API) refuses"},
	"AWS::AppSync::Resolver":              {Kind: "GraphQLApi", Status: Supported, Note: "faithfully translated as part of its parent GraphQLApi (VTL/JS byte-for-byte); not standalone — a bare one refuses"},
	"AWS::AppSync::FunctionConfiguration": {Kind: "GraphQLApi", Status: Supported, Note: "faithfully translated as part of its parent GraphQLApi (pipeline function); not standalone — a bare one refuses"},
	"AWS::AppSync::GraphQLSchema":         {Kind: "GraphQLApi", Status: Supported, Note: "faithfully translated as part of its parent GraphQLApi (schema SDL); not standalone — a bare one refuses"},
	"AWS::DynamoDB::Table":                {Kind: "Table", Status: Partial, Note: "table via kind: Table — registers name + key schema, TTL, and global secondary indexes on the aws-shim's FerretDB data layer; functions only where the aws-shim DynamoDB front door is enabled (opt-in). No capacity/throughput, local secondary indexes, streams, or per-table SSE — those block."},

	// --- API Gateway REST (v1): the whole API collates into ONE provisioning plan on its RestApi and is
	// CREATE-DEPLOYABLE via the in-cluster aws-shim doorway (which drives the apigateway REST v1 API in
	// order) — a CLI deploy, with no doorway hook, refuses rather than guessing, exactly the custom-resource
	// stance. Every other AWS::ApiGateway::* type COMPOSES into its RestApi (no standalone manifest). REST
	// v1 has no Crossplane kind: it is a stateful Postgres-backed sequence, so the create path is the
	// collate→provision hook, not a kubectl-applied object. HTTP API v2 lives as the declarative kind: HttpApi.
	"AWS::ApiGateway::RestApi":          {Kind: "aws-shim apigateway (v1)", Status: Partial, Note: "a REST (v1) API — the whole API (resource tree + methods + integrations + VTL mapping + models/validators/authorizers + deployment snapshot + stages, plus in-stack API keys/usage plans) collates into one plan and is provisioned via the in-cluster aws-shim doorway (CLI deploy refuses — no doorway). Faithful-subset caveats: COGNITO_USER_POOLS authorizers only (TOKEN/REQUEST/AWS_IAM refuse), usage-plan throttle/quota accepted-not-enforced, custom domains/WAF/gateway-responses/API-key-source=AUTHORIZER not modeled. Use kind: HttpApi for the v2/declarative model."},
	"AWS::ApiGateway::Resource":         {Kind: "aws-shim apigateway (v1)", Status: Partial, Note: "a resource-tree node — composed into its RestApi's provisioning plan (create-resource); not a standalone object."},
	"AWS::ApiGateway::Method":           {Kind: "aws-shim apigateway (v1)", Status: Partial, Note: "a method + its inline Integration/MethodResponses — composed into its RestApi's plan (put-method/put-integration/put-method-response)."},
	"AWS::ApiGateway::Deployment":       {Kind: "aws-shim apigateway (v1)", Status: Partial, Note: "a deployment snapshot — composed into its RestApi's plan; the executor snapshots once after building the whole tree and points the stages at it."},
	"AWS::ApiGateway::Stage":            {Kind: "aws-shim apigateway (v1)", Status: Partial, Note: "a named stage (+ variables) — composed into its RestApi's plan (create-stage)."},
	"AWS::ApiGateway::Model":            {Kind: "aws-shim apigateway (v1)", Status: Partial, Note: "a JSON-Schema model (request validation) — composed into its RestApi's plan (create-model), validated by the shared internal/apigwschema tier."},
	"AWS::ApiGateway::RequestValidator": {Kind: "aws-shim apigateway (v1)", Status: Partial, Note: "a (validateRequestBody, validateRequestParameters) validator — composed into its RestApi's plan (create-request-validator)."},
	"AWS::ApiGateway::Authorizer":       {Kind: "aws-shim apigateway (v1)", Status: Partial, Note: "a method authorizer — composed into its RestApi's plan. COGNITO_USER_POOLS is enforced at invoke; TOKEN/REQUEST (Lambda) + AWS_IAM refuse fail-closed."},
	"AWS::ApiGateway::ApiKey":           {Kind: "aws-shim apigateway (v1)", Status: Partial, Note: "an API key — composed into the sole in-stack RestApi's plan (create-api-key). A method with apiKeyRequired gates on an enabled key associated via a usage plan to the api+stage; throttle/quota accepted-not-enforced. With no in-stack RestApi (or more than one) it blocks rather than guessing which api it unlocks."},
	"AWS::ApiGateway::UsagePlan":        {Kind: "aws-shim apigateway (v1)", Status: Partial, Note: "a usage plan — composed into the sole in-stack RestApi's plan (create-usage-plan); its apiStages decide which stage an associated key unlocks."},
	"AWS::ApiGateway::UsagePlanKey":     {Kind: "aws-shim apigateway (v1)", Status: Partial, Note: "associates an API key with a usage plan — composed into the RestApi's plan (create-usage-plan-key)."},

	// --- partial: a doorway/backing kind exists; the mapping is lossy or collated ---
	"AWS::Cognito::UserPool":       {Kind: "UserPool", Status: Partial, Note: "a managed user pool -> kind: UserPool (PoolName->realm; an in-stack UserPoolClient collates into spec.clientId). Cognito-specific config — MfaConfiguration ON/OPTIONAL, LambdaConfig triggers, custom schema — is REFUSED (blocked at the translate gate), not silently dropped. The runtime user-pool data plane (SignUp/InitiateAuth, RS256 JWTs) is the aws-shim cognito-idp doorway (#171)."},
	"AWS::Cognito::UserPoolClient": {Kind: "UserPool(client)", Status: Partial, Note: "the pool's app client collates into its in-stack UserPool (ClientName->clientId); a standalone client, a second client, or one naming an out-of-stack pool refuses. OAuth flows/scopes/callbacks/GenerateSecret are caveats."},
	"AWS::SSM::Parameter":          {Kind: "Parameter", Status: Partial, Note: "SSM Parameter Store -> kind: Parameter (Vault KV-v2): Name->path, Value, Type (SecureString held encrypted at rest, materialized into the namespace Secret). StringList stores a plain comma-separated string; Description/AllowedPattern/DataType/Tags are advisory caveats; an Expiration policy maps to spec.expiresAt (reaper-enforced); notification policies are caveats. The runtime Parameter Store API is the aws-shim ssm doorway (#167). Through the aws-shim CloudFormation front door with SSM served, instead a parameter in that doorway's own store (Standard tier): Name is optional (CloudFormation's generated <stack>-<logical id>-<suffix>), Ref is the name, Type/Value resolve; Policies and a non-Standard Tier refuse; Description is a caveat."},
	"AWS::ECS::Service":            {Kind: "Application", Status: Partial, Note: "a Service + its referenced TaskDefinition collate into one Application (Deployment+Service+Ingress+HPA). Multi-container tasks map to a multi-container Pod (primary + sidecars) with per-container CPU/memory and shared scratch Volumes (emptyDir) + MountPoints. The LB's HTTP target port maps to the Service port (set Application.domain for Ingress+TLS). TaskRoleArn maps to the app's task role (spec.assumeRole: its SDK assumes the kind: Role of its own account on the aws-shim, no keys — a role trusting ecs-tasks.amazonaws.com, or the app's ServiceAccount; naming it takes iam:PassRole). NetworkConfiguration's awsvpc subnet places the app in a kind: Subnet (real OVN isolation, #120; a raw subnet- id refuses). Security-group isolation maps via kind: SecurityGroup (a standalone AWS::EC2::SecurityGroup now translates; attaching it to this workload via SecurityGroupIds is the follow-on); host-path/EFS volumes, container DependsOn ordering, and ExecutionRoleArn do NOT transfer."},
	"AWS::ECS::TaskDefinition":     {Kind: "Application (container)", Status: Partial, Note: "the container spec — collated into the referencing Service's Application (containers->pod containers, Cpu/Memory->requests/limits, shared Volumes->emptyDir + MountPoints); a bare TaskDefinition provisions nothing"},
	"AWS::ECS::Cluster":            {Kind: "(implicit)", Status: Partial, Note: "a grouping with no open-infra counterpart (the k3s cluster is the cluster) — provisions nothing"},

	// --- unsupported: no backing kind / explicitly out of scope for v1 (refused) ---
	// These refuse with a pointer to the open-infra path rather than the bare default, so a
	// lift-and-shift assessment reads as guidance, not a dead end. None is a silent approximation.
	"AWS::ElasticLoadBalancingV2::LoadBalancer": {Status: Unsupported, Note: "no standalone load-balancer device. An HTTP/HTTPS app's load balancer IS its ingress: express it with a kind: Application's expose/domain (Traefik L7 + cert-manager TLS), and scale with the Application's autoscaling (HPA). A pure-L4 NLB (non-HTTP) has no separate provisioned analog. Author the exposure on the workload, not as a resource."},
	"AWS::ElasticLoadBalancingV2::Listener":     {Status: Unsupported, Note: "a listener is part of the load balancer, which on open-infra is the workload's ingress — set the port/TLS on the kind: Application expose/domain; there is no standalone listener resource."},
	"AWS::ElasticLoadBalancingV2::ListenerRule": {Status: Unsupported, Note: "path/host routing lives on the kind: Application's ingress (domain + path), not a standalone rule resource."},
	"AWS::ElasticLoadBalancingV2::TargetGroup":  {Status: Unsupported, Note: "there is no separate target group: a kind: Application's Service selects its own pods, and the ingress routes to it. Express health checks / ports on the workload."},
	"AWS::ElasticLoadBalancing::LoadBalancer":   {Status: Unsupported, Note: "classic ELB — same as ELBv2: an HTTP/HTTPS app's load balancer is its ingress (kind: Application expose/domain, Traefik + cert-manager); no standalone device."},
	"AWS::AutoScaling::AutoScalingGroup":        {Status: Unsupported, Note: "for stateless horizontal scale, a kind: Application scales its pods via autoscaling (HPA) — express desired/min/max there rather than as a group of VMs. A VM-level pool analog (scaling kind: VirtualMachine replicas) is planned, not yet available; until then a fleet of identical VMs is authored as explicit kind: VirtualMachine resources."},
	"AWS::AutoScaling::LaunchConfiguration":     {Status: Unsupported, Note: "the launch shape (image/size/user-data) is expressed inline on a kind: VirtualMachine, not as a standalone launch template; there is no group to launch into (see AutoScalingGroup)."},
	"AWS::EC2::LaunchTemplate":                  {Status: Unsupported, Note: "the VM shape (os/cpu/memory/userData/disk) is authored inline on a kind: VirtualMachine; there is no standalone reusable launch template resource."},
	"AWS::CloudFormation::Stack":                {Kind: "Stack", Status: Partial, Note: "a nested stack is a stack of its own through the aws-shim CloudFormation front door (nested_stacks.go): its child template is read from its TemplateURL in the shim's own S3 (as the caller, never fetched over the network) and deployed as a child stack with its own record, events and Outputs (Fn::GetAtt <Stack>.Outputs.<Key>); its StackId is the resource's physical id, and deleting or rolling back the parent deletes it. NotificationARNs refuse; Tags are a caveat; an update of the parent that would add, remove or change a nested stack is refused. The cfn CLI instead flattens nested stacks into the parent before planning (FlattenNested)"},
	// AWS::CloudFormation::CustomResource + Custom::* are handled in Lookup (customResourceEntry, #269).

	// --- CloudFront: a narrow static-site subset (translate_cloudfront.go) ---
	// A distribution over a private S3 bucket becomes a kind: StaticSite (nginx syncing the bucket behind a
	// Traefik Ingress + cert-manager TLS). There is no edge tier, so only the static-site shape translates;
	// every other distribution feature refuses at the translate gate with its reason.
	"AWS::CloudFront::Distribution":                   {Kind: "StaticSite", Status: Partial, Note: "a narrow static-site subset -> kind: StaticSite serving the template's in-stack S3 bucket (which stays a kind: Bucket). Translates: ONE S3 REST origin over an in-stack AWS::S3::Bucket, read via an in-stack OAC or OAI (or neither) — realized by the site's own scoped MinIO credentials, so the bucket stays private; Aliases -> spec.domain/domains with TLS from cert-manager (ViewerCertificate.AcmCertificateArn, e.g. an in-stack ACM certificate, is not used — openinfra-issuer issues the certificate); CustomErrorResponses 403/404 -> /index.html (200) -> SPA fallback, or -> an error page (404) -> errorDocument; DefaultRootObject -> indexDocument; a ResponseHeadersPolicy (in-stack, or the AWS managed SecurityHeadersPolicy) -> spec.responseHeaders; Fn::GetAtt DomainName -> the first Alias. Caveats (accepted, not emulated): there is NO edge cache (cache/origin-request policies, TTLs, Compress, PriceClass), the site answers HTTPS only (ViewerProtocolPolicy redirect-to-https/allow-all), access Logging, HttpVersion/IPV6Enabled/Comment/Tags, S3 object metadata (Content-Type/Cache-Control/Content-Encoding) is not served, content re-syncs every 30s (the aws-shim serves CreateInvalidation/GetInvalidation/ListInvalidations on Ref <Distribution>: Completed once the site has re-synced). REFUSED: no Aliases (no *.cloudfront.net analog), a second origin / OriginGroups, a custom (non-S3) origin, OriginPath, path-pattern CacheBehaviors, Lambda@Edge / CloudFront Functions, signed URLs (TrustedKeyGroups/Signers), field-level encryption, real-time logs, geo restriction, WebACLId (WAF), continuous deployment/staging, write methods, CORS/remove-headers policy config, and Enabled: false."},
	"AWS::CloudFront::OriginAccessControl":            {Kind: "StaticSite(origin access)", Status: Partial, Note: "an s3 origin access control composes into the referencing distribution's kind: StaticSite: the site reads the bucket with its own scoped MinIO credentials (the OAC analog), so the bucket stays private; the S3 BucketPolicy statement granting the cloudfront.amazonaws.com service read (conditioned on aws:SourceArn of an in-stack distribution) is realized by the site, not stored as a MinIO policy. SigV4 request signing is not emulated; a non-s3 OriginAccessControlOriginType refuses. Provisions nothing on its own."},
	"AWS::CloudFront::CloudFrontOriginAccessIdentity": {Kind: "StaticSite(origin access)", Status: Partial, Note: "a legacy origin access identity composes into the referencing distribution's kind: StaticSite like an OAC: the site's scoped MinIO credentials are the reader, and the BucketPolicy statement granting the identity read (CanonicalUser !GetAtt <OAI>.S3CanonicalUserId, or its IAM ARN) is realized by the site, not stored. An identity outside the stack refuses. Provisions nothing on its own."},
	"AWS::CloudFront::ResponseHeadersPolicy":          {Kind: "StaticSite(responseHeaders)", Status: Partial, Note: "a response headers policy composes into the referencing distribution's kind: StaticSite as spec.responseHeaders (nginx adds them to every response, errors included): SecurityHeadersConfig (Strict-Transport-Security, Content-Security-Policy, X-Content-Type-Options, X-Frame-Options, Referrer-Policy, X-XSS-Protection) and CustomHeadersConfig items. Override is moot (the origin never sets them). REFUSED: CorsConfig (dynamic CORS + preflight), RemoveHeadersConfig, a header the server sets itself (Content-Type, Server, …). ServerTimingHeadersConfig is a caveat. Provisions nothing on its own."},
	"AWS::CloudFront::CachePolicy":                    {Kind: "(implicit)", Status: Partial, Note: "accepted but NOT emulated: kind: StaticSite has no cache tier — every request is served from the synced copy of the bucket, with no cache key or TTLs. The referencing distribution carries the caveat; provisions nothing."},
	"AWS::CloudFront::OriginRequestPolicy":            {Kind: "(implicit)", Status: Partial, Note: "accepted but NOT emulated: kind: StaticSite makes no per-request origin fetch, so there are no forwarded headers/cookies/query strings to choose. The referencing distribution carries the caveat; provisions nothing."},
	"AWS::CertificateManager::Certificate":            {Kind: "StaticSite(tls)", Status: Partial, Note: "translates ONLY as the ViewerCertificate of an in-stack AWS::CloudFront::Distribution: the site's certificate for the distribution's Aliases is issued in-cluster by cert-manager, not ACM: for Aliases under a domain the operator validated (certificates.validatedDomains — ACM's domain validation, done once) by the platform's ACM-style CA (ClusterIssuer openinfra-acm, signed by the platform root and constrained to those domains), and an Alias outside them refuses, as ACM would never validate it; with no validated domains, self-signed (openinfra-issuer). No DNS/email validation records are needed, and the key options are cert-manager's. The certificate must cover the Aliases (as CloudFront requires). A certificate no included distribution references (an ELB listener's, an API domain's) refuses — it has no open-infra consumer; a private-CA (CertificateAuthorityArn) certificate refuses. Provisions nothing on its own."},
}

// customResourceEntry is the mapping for a Lambda-backed custom resource — AWS::CloudFormation::
// CustomResource and any Custom::<Name>. Both resolve to the same thing: at deploy, the in-stack
// kind: Function named by ServiceToken is invoked with the CloudFormation custom-resource event,
// and its returned Data feeds dependents' Fn::GetAtt (#269).
var customResourceEntry = MapEntry{Kind: "Function(invoke)", Status: Supported, Note: "Lambda-backed custom resource: at deploy the in-stack kind: Function named by ServiceToken (a !Ref/!GetAtt to an in-stack AWS::Lambda::Function) is invoked SYNCHRONOUSLY with the CloudFormation custom-resource event, and its returned Data resolves dependents' Fn::GetAtt (the open-infra adaptation of the pre-signed ResponseURL callback: the handler RETURNS {Status, Data} rather than PUT-ing to S3). Fail-closed: an out-of-stack / AWS-ARN ServiceToken refuses. Create + Delete (destroy) are supported; a stack UPDATE touching a custom resource refuses (destroy+recreate)."}

// Lookup returns the mapping entry for a CFN resource type. An unknown type is unsupported by
// default: the engine never guesses. A custom resource (AWS::CloudFormation::CustomResource or
// Custom::*) maps to the invoke-at-deploy backing (#269).
func Lookup(cfnType string) MapEntry {
	if e, ok := mappingTable[cfnType]; ok {
		return e
	}
	if cfnType == "AWS::CloudFormation::CustomResource" || strings.HasPrefix(cfnType, "Custom::") {
		return customResourceEntry
	}
	return MapEntry{Status: Unsupported, Note: "no backing open-infra kind"}
}

// mappable reports whether a status can be provisioned (supported outright, or partial
// with caveats). gated/unsupported cannot.
func (e MapEntry) mappable() bool { return e.Status == Supported || e.Status == Partial }
